def find_path(graph, start, goal):
    def explore(current, path, visited):
        visited.add(current)
        path.append(current)

        if current == goal:
            return path

        for neighbor in graph.get(current, []):
            if neighbor not in visited:
                result = explore(neighbor, path.copy(), visited)
                if result:
                    return result

        path.pop()
        visited.remove(current)
        return None

    return explore(start, [], set())

