        return [start]  # Path found when start and goal are the same node

    visited = set()
    path_stack = [(start, [start])]  # Stack to manage the order of nodes to visit

    while path_stack:
        (current_node, path) = path_stack.pop()
        if current_node not in visited:
            visited.add(current_node)
            for node in graph[current_node]:
                if node == goal:
                    return path + [goal]  # Goal node found, add it to the path
                else:
                    path_stack.append((node, path + [node]))  # Add neighbors to the stack with updated path

    return None  # Goal node is unreachable
